base=Path('/opt/news-flow/current');root=Path('/var/lib/news-flow/recovery-all-20261123');p=base/'src/newsFlow/reviewedRecovery.mjs';old=p.read_bytes();assert b'publicationHistoryUnconfirmed' not in old and b'export function stageReviewedRecovery' in old
(root/'before-reviewedRecovery-history.mjs').write_bytes(old);p.write_bytes(b'import {articleKey,requestKey,urlAliases} from \'./identity.mjs\';\nimport {publicationHistoryUnconfirmed} from \'../web/newsOriginalPublicationContract.mjs\';\n\n// Stage only a successful frozen review. The ordinary importer still owns ES\n// writes; concurrent collector decisions and newer failures take precedence.\nexport function stageReviewedRecovery(state,row,payload,{snapshotAt}={}){\n if(!Number.isFinite(snapshotAt)||!Number.isFinite(row.checked_at)||row.checked_at<snapshotAt)throw Error(\'RECOVERY_INVALID_REVIEW_TIME\');\n if(![\'verified\',\'excluded\'].includes(row.outcome))throw Error(\'RECOVERY_NOT_VERIFIED\');\n if(row.outcome===\'verified\'&&(!payload?.doc?._id||!payload.config||!Array.isArray(payload.aliases)||!payload.aliases.includes(row.url)))throw Error(\'RECOVERY_PAYLOAD_INVALID\');\n if(row.outcome===\'excluded\'&&!row.reason?.startsWith(\'non_article:\'))throw Error(\'RECOVERY_EXCLUSION_UNPROVEN\');\n if(row.outcome===\'verified\'&&(publicationHistoryUnconfirmed(row.url,payload.config)||publicationHistoryUnconfirmed(row.url,state.articleSources?.get(row.site)?.config)||publicationHistoryUnconfirmed(payload.doc._source?.url,payload.config)))return {status:\'history_quarantine\'};\n return state.tx(()=>{\n  const db=state.db,current=db.prepare(\'SELECT * FROM article_links WHERE parse_key=?\').get(row.parse_key);\n  if(!current||current.parse_status!==\'fail\'||current.error!==row.old_reason||(current.reviewed_at||0)!==(row.old_reviewed_at||0)||current.config_version!==row.old_config_version)return {status:\'concurrent_change\'};\n  const aliases=new Set([row.url,...payload?.aliases||[]]);\n  const keys=new Set([...aliases].flatMap(urlAliases).map(requestKey));\n  for(const key of keys){\n   if(db.prepare(\'SELECT 1 FROM url_failures WHERE url_key=? AND last_at>?\').get(key,row.checked_at))return {status:\'newer_failure\'};\n  }\n  for(const url of aliases){\n   const other=db.prepare(\'SELECT * FROM article_links WHERE parse_key=?\').get(articleKey(url));\n   if(other&&other.parse_key!==row.parse_key&&([\'queued\',\'running\',\'pending\'].includes(other.parse_status)||(other.reviewed_at||0)>=snapshotAt))return {status:\'alias_concurrent_change\'};\n  }\n  if(row.outcome===\'verified\'){\n   state.offer(payload.doc,payload.config,[...aliases]);\n   state.remember({url:row.url,site:row.site},\'done\',\'verified_outbox\');\n   db.prepare("UPDATE article_links SET parse_status=\'done\',error=NULL,reviewed_at=?,config_version=? WHERE parse_key=?").run(row.checked_at,state.configVersions.get(row.site)||\'\',row.parse_key);\n  }else{\n   db.prepare("UPDATE article_links SET parse_status=\'skipped\',error=?,reviewed_at=? WHERE parse_key=?").run(row.reason,row.checked_at,row.parse_key);\n   state.remember({url:row.url,site:row.site},\'done\',row.reason);\n  }\n  const clear=db.prepare("DELETE FROM url_failures WHERE url_key=? AND last_at<=? AND (?=\'verified\' OR role=\'article\')");\n  for(const key of keys)clear.run(key,row.checked_at,row.outcome);\n  state.event(\'manual_frozen_recovery\',{site:row.site,url:row.url,outcome:row.outcome,evidenceFile:row.evidence_file,checkedAt:row.checked_at,paidAiCalls:0});\n  return {status:row.outcome===\'verified\'?\'staged\':\'excluded\',id:payload?.doc?._id||null};\n });\n}\n\n// Existing minute-precision documents can legitimately lack native seconds.\n// A different minute is retained for review rather than rewriting history.\nexport function recoveryPublicationConflict(expected,stored){\n if(!/T\\d\\d:\\d\\d:/.test(expected||\'\')||!/T\\d\\d:\\d\\d:/.test(stored||\'\'))return false;\n const a=Date.parse(expected),b=Date.parse(stored);\n return Number.isFinite(a)&&Number.isFinite(b)&&Math.floor(a/60000)!==Math.floor(b/60000);\n}\n');t=base/'test/news-reviewed-recovery.test.mjs';oldtest=t.read_bytes();t.write_bytes(b'import test from \'node:test\';import assert from \'node:assert/strict\';import {DatabaseSync} from \'node:sqlite\';\nimport {stageReviewedRecovery,recoveryPublicationConflict} from \'../src/newsFlow/reviewedRecovery.mjs\';\nfunction fixture(){const db=new DatabaseSync(\':memory:\');db.exec("CREATE TABLE article_links(parse_key TEXT PRIMARY KEY,url TEXT,site TEXT,parse_status TEXT,error TEXT,reviewed_at INTEGER,config_version TEXT);CREATE TABLE url_failures(url_key TEXT PRIMARY KEY,role TEXT,last_at INTEGER);INSERT INTO article_links VALUES(\'https://example.com/a\',\'https://example.com/a\',\'example.com\',\'fail\',\'old\',10,\'v1\');INSERT INTO url_failures VALUES(\'https://example.com/a\',\'article\',20)");let offers=0;const state={db,configVersions:new Map([[\'example.com\',\'v1\']]),tx:fn=>{db.exec(\'BEGIN\');try{const r=fn();db.exec(\'COMMIT\');return r;}catch(e){db.exec(\'ROLLBACK\');throw e;}},offer:()=>offers++,remember:()=>{},event:()=>{}},row={parse_key:\'https://example.com/a\',url:\'https://example.com/a\',site:\'example.com\',old_reason:\'old\',old_reviewed_at:10,old_config_version:\'v1\',outcome:\'verified\',checked_at:40},payload={doc:{_id:\'id\'},config:{},aliases:[row.url]};return {db,state,row,payload,offers:()=>offers};}\ntest(\'verified review stages once and clears only its old failure\',()=>{const f=fixture();assert.equal(stageReviewedRecovery(f.state,f.row,f.payload,{snapshotAt:30}).status,\'staged\');assert.equal(f.offers(),1);assert.equal(f.db.prepare(\'SELECT count(*) n FROM url_failures\').get().n,0);assert.equal(stageReviewedRecovery(f.state,f.row,f.payload,{snapshotAt:30}).status,\'concurrent_change\');assert.equal(f.offers(),1);f.db.close();});\ntest(\'new failure or concurrent queue state cannot be overwritten\',()=>{for(const mutation of ["UPDATE url_failures SET last_at=41","UPDATE article_links SET parse_status=\'queued\'","UPDATE article_links SET reviewed_at=31","UPDATE article_links SET config_version=\'v2\'"]){const f=fixture();f.db.exec(mutation);assert.notEqual(stageReviewedRecovery(f.state,f.row,f.payload,{snapshotAt:30}).status,\'staged\');assert.equal(f.offers(),0);f.db.close();}});\ntest(\'alias concurrent work prevents mutation and unexpected outcome fails\',()=>{const f=fixture();f.db.prepare("INSERT INTO article_links VALUES(?,?,?,\'running\',NULL,0,\'v1\')").run(\'https://example.com/b\',\'https://example.com/b\',\'example.com\');f.payload.aliases.push(\'https://example.com/b\');assert.equal(stageReviewedRecovery(f.state,f.row,f.payload,{snapshotAt:30}).status,\'alias_concurrent_change\');assert.equal(f.db.prepare(\'SELECT count(*) n FROM url_failures\').get().n,1);assert.throws(()=>stageReviewedRecovery(f.state,{...f.row,outcome:\'failed\'},f.payload,{snapshotAt:30}),/NOT_VERIFIED/);f.db.close();});\ntest(\'non-article exclusion preserves non-article role failure\',()=>{const f=fixture();f.db.exec("UPDATE url_failures SET role=\'seed\'");const r=stageReviewedRecovery(f.state,{...f.row,outcome:\'excluded\',reason:\'non_article:category\'},null,{snapshotAt:30});assert.equal(r.status,\'excluded\');assert.equal(f.db.prepare(\'SELECT parse_status FROM article_links\').get().parse_status,\'skipped\');assert.equal(f.db.prepare(\'SELECT count(*) n FROM url_failures\').get().n,1);f.db.close();});\n\ntest(\'legacy minute precision is preserved while different original minutes require review\',()=>{assert.equal(recoveryPublicationConflict(\'2026-11-20T01:02:49Z\',\'2026-11-20T01:02:00Z\'),false);assert.equal(recoveryPublicationConflict(\'2026-11-20T01:02:49Z\',\'2026-11-20T01:01:59Z\'),true);assert.equal(recoveryPublicationConflict(\'2026-11-20T01:02:49Z\',\'2026-11-20T08:02:49Z\'),true);assert.equal(recoveryPublicationConflict(\'2026-11-20\',\'2026-11-20T00:00:00Z\'),false);assert.equal(recoveryPublicationConflict(\'invalid\',\'2026-11-20T00:00:00Z\'),false);});\n\ntest(\'requested URL history quarantine survives a verified canonical payload\',()=>{for(const mode of [\'owner\',\'requested_source\']){const f=fixture();if(mode===\'owner\')f.payload.config.originalPublicationUncertainUrls=[f.row.url];else f.state.articleSources=new Map([[f.row.site,{config:{originalPublicationUncertainUrls:[f.row.url]}}]]);assert.equal(stageReviewedRecovery(f.state,f.row,f.payload,{snapshotAt:30}).status,\'history_quarantine\');assert.equal(f.offers(),0);assert.equal(f.db.prepare(\'SELECT parse_status FROM article_links\').get().parse_status,\'fail\');assert.equal(f.db.prepare(\'SELECT count(*) n FROM url_failures\').get().n,1);f.db.close();}});\n')
